/** The sixteen ANSI terminal slots, in SGR 30–37 / 90–97 order. */
struct RiffetAnsiValues: Sendable {
    let light: [RiffetRGBA]
    let dark: [RiffetRGBA]

    init(light: [RiffetRGBA], dark: [RiffetRGBA]) {
        self.light = light
        self.dark = dark
    }

    /** Parses a custom theme's stored ANSI colours; nil unless each half has sixteen readable values. */
    init?(light: [String], dark: [String]) {
        guard light.count == 16, dark.count == 16,
              let light = RiffetAnsiValues.parse(light),
              let dark = RiffetAnsiValues.parse(dark)
        else { return nil }
        self.init(light: light, dark: dark)
    }

    private static func parse(_ values: [String]) -> [RiffetRGBA]? {
        var colors: [RiffetRGBA] = []
        colors.reserveCapacity(values.count)
        for value in values {
            guard let color = RiffetRGBA(hex: value) else { return nil }
            colors.append(color)
        }
        return colors
    }
}

